{
  "name": "Modbus串口通信接口",
  "name_en": "Modbus Serial Communication Interface",
  "manufacturer": "",
  "description": "一种通过串行端口与支持Modbus协议的实验设备进行通信的接口装置，常见于RS-232或RS-485连接。实验中可用于配置通信参数，并与传感器、控制器、仪表等设备建立数据链路。",
  "description_en": "A serial interface used to communicate with laboratory instruments that support the Modbus protocol, typically over RS-232 or RS-485. In laboratory use, it is used to configure communication parameters and establish data links with sensors, controllers, meters, and other instruments.",
  "tag_hints": [
    "Modbus RTU",
    "serial communication",
    "RS-485",
    "RS-232",
    "instrument connectivity",
    "baud rate configuration"
  ],
  "actions": [
    {
      "action_name": "auto-get_port",
      "description": "获取串口端口",
      "description_en": "get serial port"
    },
    {
      "action_name": "auto-set_port",
      "description": "设置串口端口",
      "description_en": "set serial port"
    },
    {
      "action_name": "auto-get_stopbits",
      "description": "获取停止位",
      "description_en": "get stop bits"
    },
    {
      "action_name": "auto-set_stopbits",
      "description": "设置停止位",
      "description_en": "set stop bits"
    },
    {
      "action_name": "auto-get_bytesize",
      "description": "获取数据位长度",
      "description_en": "get data bits"
    },
    {
      "action_name": "auto-set_bytesize",
      "description": "设置数据位长度",
      "description_en": "set data bits"
    },
    {
      "action_name": "auto-get_parity",
      "description": "获取奇偶校验设置",
      "description_en": "get parity setting"
    },
    {
      "action_name": "auto-set_parity",
      "description": "设置奇偶校验",
      "description_en": "set parity setting"
    },
    {
      "action_name": "auto-get_baudrate",
      "description": "获取波特率",
      "description_en": "get baud rate"
    },
    {
      "action_name": "auto-set_baudrate",
      "description": "设置波特率",
      "description_en": "set baud rate"
    },
    {
      "action_name": "auto-get_timeout",
      "description": "获取串口读取超时时间",
      "description_en": "get serial read timeout"
    },
    {
      "action_name": "auto-set_timeout",
      "description": "设置串口读取超时时间",
      "description_en": "set serial read timeout"
    },
    {
      "action_name": "auto-get_serial_settings",
      "description": "获取当前串口设置",
      "description_en": "get current serial settings"
    }
  ]
}

